import { ToastAndroid, Button } from 'react-native';

<Button
  title="Show Toast"
  onPress={() => {
    ToastAndroid.show('Hello Toast!', ToastAndroid.SHORT);
  }}
/>

<Button
  title="Toast Center"
  onPress={() => {
    ToastAndroid.showWithGravity('Centered Toast', ToastAndroid.LONG, ToastAndroid.CENTER);
  }}
/>

<Button
  title="Toast With Offset"
  onPress={() => {
    ToastAndroid.showWithGravityAndOffset('Offset Toast', ToastAndroid.LONG, ToastAndroid.BOTTOM, 50, 100);
  }}
/>
